import{_ as a,o as e,c as o,a2 as t}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"裸机云升级/降级操作指南","description":"","frontmatter":{"title":"裸机云升级/降级操作指南"},"headers":[],"relativePath":"ops-knowledge-base/baremetal/upgrade-downgrade-guide.md","filePath":"ops-knowledge-base/baremetal/upgrade-downgrade-guide.md","lastUpdated":1794309341000}'),i={name:"ops-knowledge-base/baremetal/upgrade-downgrade-guide.md"};function r(p,l,d,s,n,u){return e(),o("div",null,[...l[0]||(l[0]=[t('<p>用途： 本文档主要介绍裸机云升级/降级功能的详细操作步骤及注意事项，帮助客户顺利完成服务器配置调整。</p><p>适用产品：裸机云（Bare Metal Cloud）</p><h2 id="一、操作前须知" tabindex="-1">一、操作前须知 <a class="header-anchor" href="#一、操作前须知" aria-label="Permalink to &quot;一、操作前须知&quot;">​</a></h2><p>在进行升级/降级操作前，请务必了解以下重要事项：</p><ol><li>操作前提</li></ol><ul><li>服务器须处于&quot;已付款&quot;状态，方可进行升级/降级操作。</li><li>升级/降级操作完成后，服务器会自动重启。请提前保存好业务数据，以免造成数据丢失。</li></ul><ol start="2"><li>降级退款说明 周期内中途降级配置，不支持降级配置部分退款，但续费价格和配置会在您操作后随之调整。</li></ol><h2 id="二、操作步骤" tabindex="-1">二、操作步骤 <a class="header-anchor" href="#二、操作步骤" aria-label="Permalink to &quot;二、操作步骤&quot;">​</a></h2><p><strong>步骤一：进入服务器管理界面</strong></p><ol><li>登录 Raksmart 客户后台。</li><li>在左侧菜单栏选择&quot;产品管理&quot; → &quot;裸机云&quot;。</li><li>找到需要升级/降级的服务器（确保服务器为&quot;已付款&quot;状态）。</li><li>点击产品名称，进入服务器管理页面。</li></ol><p><strong>步骤二：进入升级/降级页面</strong></p><ol><li>在服务器管理页面中，点击&quot;升/降级&quot;按钮。</li><li>系统会弹出提示窗口，内容如下：</li></ol><p>【提示】 周期内中途降级配置，不支持降级配置部分退款，但续费价格和配置会在您操作后随之调整。 裸机云产品CPU、内存、经典网络增减IP，以上内容升降级操作云机会自动重启，建议提前保存备份好数据后操作。</p><ol start="3"><li>仔细阅读提示内容后，点击&quot;确定&quot;，进入升级/降级配置页面。</li></ol><p><strong>步骤三：选择需要调整的配置</strong></p><p>进入升级/降级页面后，可根据需求选择调整以下配置：</p><ul><li>带宽：选择需要升级到的带宽大小</li><li>流量：选择对应的流量等级</li><li>防御（高防）：部分区域支持升级防御（并非所有地区都有）</li><li>IP数量：普通IP最多可升级到64个</li><li>内存：选择需要升级的内存大小</li><li>HDD数据盘：可升级容量</li><li>SSD数据盘：可升级容量，HDD和SSD可同时使用</li></ul><p><strong>步骤四：确认并提交</strong></p><ol><li>选择好需要调整的配置后，点击&quot;继续&quot;按钮。</li><li>系统会生成对应的账单。</li><li>注意：如果同时升级多个项目，每个升级项目会生成独立的账单，需逐一支付。</li><li>完成支付后，服务器将自动重启并应用新的配置。</li></ol><h2 id="三、配置查看" tabindex="-1">三、配置查看 <a class="header-anchor" href="#三、配置查看" aria-label="Permalink to &quot;三、配置查看&quot;">​</a></h2><p>升级/降级完成后，可在服务器管理页面的&quot;配置选项&quot;中查看更新后的配置信息。</p><p>详细操作请参考：《<a href="/ops-knowledge-base/baremetal/console-guide.html">裸机云控制台操作指南</a>》——&quot;配置选项&quot;章节。</p><h2 id="四、常见问题" tabindex="-1">四、常见问题 <a class="header-anchor" href="#四、常见问题" aria-label="Permalink to &quot;四、常见问题&quot;">​</a></h2><p>Q1：为什么CPU不能升级？ A1：CPU型号为服务器的核心硬件配置，由物理芯片决定，购买后无法更换。如确实需要更高性能的CPU，建议新购更高配置的服务器。</p><p>Q2：为什么线路不能更换？ A2：线路类型涉及网络架构和路由策略，购买后不可更改。如需更换线路，建议新购对应线路的服务器。</p><p>Q3：降级后能退款吗？ A3：不能。周期内中途降级配置，不支持降级配置部分退款。降级后续费价格会随之调整，但已支付周期内的差价不予退还。</p><p>Q4：升级/降级操作会影响服务器运行吗？ A4：会。升降级操作完成后服务器会自动重启。请在操作前保存好业务数据，建议在业务低峰期进行操作。</p><p>Q5：为什么我在升级页面看不到某个配置选项？ A5：如果某个配置项在升级/降级页面中未显示，说明该选项不支持升降级。例如CPU、系统盘、线路等均不支持调整。</p><p>Q6：服务器欠费或过期可以升级吗？ A7：不可以。升级裸机云需要机器处于已付款状态。请先续费后再进行操作。</p>',29)])])}const h=a(i,[["render",r]]);export{g as __pageData,h as default};
